/**
 * Writes src/engine/data-spell-facts.ts from OpenDota's game constants: each hero's spells, whether a
 * dispel removes them and whether they go through Black King Bar.
 *
 *   npm run spell-facts
 *
 * Rerun it after a patch and review the diff: every changed line changes which answer items the engine
 * offers. Fix a wrong fact in OVERRIDES (src/engine/spell-facts.ts), not in the generated file.
 */
import { writeFileSync } from "node:fs";
import { fetchSpellFacts } from "../src/data/spell-facts";

const OUT = new URL("../src/engine/data-spell-facts.ts", import.meta.url);

const facts = await fetchSpellFacts();
const heroes = Object.keys(facts).sort((a, b) => a.localeCompare(b));
const lines = heroes.flatMap((hero) => [
  `  ${JSON.stringify(hero)}: [`,
  ...(facts[hero] ?? []).map((spell) => `    ${JSON.stringify(spell)},`),
  "  ],",
]);
writeFileSync(
  OUT,
  [
    `// Generated by \`npm run spell-facts\` from OpenDota's game constants on ${new Date().toISOString().slice(0, 10)}.`,
    "// Do not edit by hand: fix a wrong fact in OVERRIDES (spell-facts.ts), and rerun the script after a patch.",
    'import type { SpellFacts } from "./spell-facts";',
    "",
    "export const SPELL_FACTS: SpellFacts = {",
    ...lines,
    "};",
    "",
  ].join("\n"),
);
console.log(`Wrote spell facts for ${heroes.length} heroes.`);
